   "context": "<strong>√ඉ</strong> යනු; <strong>අජ්ඣයනෙ</strong>, හැදෑරීමෙහි වැටේ; <strong>භවතා අධීයතං ඉති</strong>, භවත්හු විසින් හදාරන ලදැයි යන අර්ථයෙහි; ඉකාරාගම් වුද්ධි ; “එ අය” යන සුතුරෙන් ‘අය’ යන ආදෙශ “අජ්ඣො අධි” යන සුතුරෙන් අජ්ඣ යන ආදෙශයෝ වෙත්; <strong>අජ්ඣයිතබ්බං</strong> යනු වී; <strong>ණ්‍යප්පච්චයෙ තු</strong>, ණ්‍යප්‍රත්‍යයා පරකල්හි වනාහි; වෘද්ධි යකාරයාට ද්විත්තද අජ්ඣ යන ආදෙශ වද අජ්ඣෙය්‍යං යනු වේ; <strong>කිච්චාති</strong>, කිච්චා යනු; <strong>අධිකිච්ච</strong>, අවශ්‍යය අධමිණය යන මේ අර්ථයෙහිද, අධමිණ නම් දරදීගත් තැනැත්තේයි*<sup class=\"sn-mark sn-cur\">[1]</sup>; <strong>භවතා</strong>, පින්වත්හු විසින්; <strong>ගෙහං කත්තබ්බං</strong>, අවශ්‍යයෙන් ගෙයක්කට යුත්තේයි; “<strong>කරණීයං</strong>” යනු අනීය වූ තැනි; <strong>කාරියං</strong> යනු ණ්‍ය වූ තැනි; <strong>දානීයං දෙය්‍යං</strong> යනුත් එසේමැයි.",
   "html": "<p>*අධමො ඉණො අධමිණො - ඉණගාහීති අත්ථො - යී ටීකා</p>"
