   "title": "කිච්චකිත්ථම්භවො- ම.ඡ.ස. මුද්",
   "context": "කිච්චකිත්සම්භවො<sup class=\"sn-mark sn-cur\">[1]</sup> ධාතු-ප්පච්චයෙහිපි වෙදියො.",
   "html": "<p>කිච්චකිත්ථම්භවො- ම.ඡ.ස. මුද්‍රණදොස</p>"
