   "context": "",
   "html": "<p>උපක්කිලෙසෙ බ්‍යපනුජ්ජ සබ්බෙති සබ්බෙ චිත්තස්ස උපක්කිලෙසෙ බ්‍යපනුජ්ජ පනුදිත්වා පජහිත්වා විනොදෙත්වා බ්‍යන්තීකරිත්වා අනභාවං ගමෙත්වාති – උපක්කිලෙසෙ බ්‍යපනුජ්ජ සබ්බෙ. (චූලනිද්.)</p>"
