   "context": "",
   "html": "<p>එවං <strong>පස්සන්තො තරුපණ්ණානි</strong> පච්චක්ඛතො එව නිච්චසඤ්ඤං <strong>පනූදති</strong> පජහති, (විසු.ම.ටී.)</p>"
