   "title": "මක්කටො කතගුණජානනකො ආචාරසම්පන්නො සීලවා නා…",
   "context": "",
   "html": "<p>‘‘මක්කටො කතගුණජානනකො ආචාරසම්පන්නො සීලවා නාම අත්ථී’’ති කහං තයා සුතො වා දිට්ඨො වා (ජා.අ.)</p>"
