   "context": "<strong>හර</strong> හරණෙ, හරතීති හත්තා, භින්දතීති භෙත්තා, භෙදිතා වා, ඡින්දතීති ඡෙත්තා, දදාතීති දාතා, භොජනස්ස දාතා<sup class=\"sn-mark sn-cur\">[1]</sup> භොජනදාතා, සන්දහතීති සන්ධාතා, අවචි, වචති, වක්ඛතීති වා වත්තා, ‘‘භුජාදීනමන්තො නො ද්වි චා’’ති ධාත්වන්තලොපො, ද්විත්තඤ්ච, භුඤ්ජතීති භොත්තා, අබුජ්ඣි, බුජ්ඣති, බුජ්ඣිස්සතීති වා බුජ්ඣිතා, <strong>ය</strong>කා<strong>රි</strong>කාරාගමා, ජානාතීති ඤාතා, ජිනාතීති ජෙතා, සුණාතීති සොතා, ගණ්හාතීති ගහෙතා, භවතීති භවිතා, සරතීති සරිතා, ගච්ඡතීති ගන්තා. ‘‘ගම ඛන හනාදීනං තුං තබ්බාදීසු න’’ඉති ධාත්වන්තස්ස නත්තං. එවං ඛනතීති ඛන්තා, හනතීති හන්තා, මඤ්ඤතීති මන්තා, පාලෙතීති පාලෙතා, පාලයිතා.",
