   "context": "",
   "html": "<p><strong>අනෙන</strong>, මේ කැවිට කරණ කොට ගෙන; <strong>පතුජ්ජතෙ</strong>, විදුනා ලැබේනුයි පීඩා කරනු ලැබේනුයි ; <strong>පතොදො</strong>, කැවිට නම් වේ. √තුද බ්‍යථනෙ; තුද යනු; <strong>බ්‍යථනෙ</strong>, පීඩා කිරීමෙහි වැටේ;</p>"
