   "title": "භයදස්සාවී, භය දක්නා සුලු. √දිස පෙක්ඛනෙ…",
   "context": "",
   "html": "<p><strong>භයදස්සාවී</strong>, භය දක්නා සුලු. √දිස පෙක්ඛනෙ; ආදීනවං පස්සිතුං සීලං යස්සාති වා ආදීනවදස්සන සීලො ආදීනවදස්සන ධම්මො ආදීනව දස්සනෙ සාධුකාරීති වා සීලෙන ආදීනවං අපස්සි පස්සති යනාදි ද වේ. <strong>ආදීනවදස්සාවී</strong>, ආදීනව දක්නාසුලු.</p>"
