   "html": "<p>√හන යනු; <strong>හිංසා</strong>, හිංසායෙහි ද; <strong>ගතිසු</strong>, ගමන්හිද වැටේ. සං හන්ති, සේ; සමග්ගං කම්මං යනාදිසේයි; <strong>හන්ති</strong>, නසානුයි නොහොත්; පැමිණේනුයි. “හන්ති” යී ප්‍රත්‍යය ගත් කල්හි නසා නුයි පැමිණේනුයි අර්ථද්වයටමයි, සාමාන්‍යයෙන් වාක්‍ය ගෙන නැවත අර්ථද්වයට “සමග්ගං” යනාදීන් වාක්‍ය ගන්නා ලැබේ; සමග්ගං කම්මං සමුපගච්චතීති වා සංඝො සම්මදෙව කිලෙසදරථෙ හන්තීතිවා සංඝො, <strong>සමග්ගං කම්මං</strong>, සමඟ වූ උපොසථාදි කර්මයට යෙදේනුයි පැමිණේනුයි යන අර්ථයෙහි; <strong>සම්මදෙව</strong>, මනාකොටම; <strong>කිලෙසදරථෙ</strong>, ක්ලෙශ පීඩාවන්; <strong>හන්තිති</strong>; නසානුයි යන අර්ථයෙහිද සංඝ නම් වේ;</p>"
