   "title": "තිප්පච්චයෙ, “ඉත්ථියමතිය වො වා”, යන සූත්‍…",
   "context": "",
   "html": "<p><strong>තිප්පච්චයෙ</strong>, “ඉත්ථියමතිය වො වා”, යන සූත්‍රයෙන් කළ තිප්‍රත්‍යයා පරකල්හි; <strong>තාය</strong>, ඒ ප්‍රඥාව කරණ කොටගෙන දැන්ම හෝ දත්නුයි හෝ; <strong>සිජ්ඣනං සිජ්ඣති තායාති සිද්ධි. තාය</strong>, ඒ වීම කරණ කොටගෙන යම් කටයුත්තක්හුගේ වීම හෝ යම්කටයුත්තක් වේනුයි හෝ; <strong>වඩ්ඪනං වඩ්ඪති එතායාති වඩ්ඪි</strong>, මේ අභිවෘද්ධිය කරණකොටගෙන යමක්හුගේ වැඩීම හෝ වඩීනුයි හෝ පොලී මෙතන වැඩි නම් වේ. දන්නා ලබන දෙය දත යුතු දෙය “බොද්ධබ්බ” නම් වේ; බුජ්ඣනං බුජ්ඣිතබ්බං.</p>"
