   "context": "<strong>සො</strong>, හෙතෙම; <strong>මයා</strong>, මා විසින්, අනුශාසනා කරන ලදි; අනුශාසනං අනුසිට්ඨි “දට්ඨය්‍යං” යන තන්හි <sup class=\"sn-mark sn-cur\">[1]</sup>* ණ්‍යො ච &quot; යන සූත්‍රයෙහි ච ග්‍රහණයෙන් තය්‍ය ප්‍රත්‍යය වේ; <strong>පස්සිතුං</strong>, දක්නට යන අර්ථයෙහි; <strong>දට්ඨුං ගච්ඡති</strong>, දක්නට යේ;",
