   "context": "<strong>වස්ස</strong> සෙචනෙ,<sup class=\"sn-mark sn-cur\">[1]</sup> අවස්සීති වුට්ඨො දෙවො, පවිසිත්ථාති<sup class=\"sn-mark sn-cur\">[2]</sup> පවිට්ඨො, උද්දිසීයිත්ථාති උද්දිට්ඨො.",
   "html": "<p>ජිසු නිසු විසු මිසු වස්ස සෙචනෙ. ජෙසති. නෙසති. වෙසති. මෙසති. දෙවො වස්සති. (සද්දනීති) (වස සෙචනෙ - ම.ඡ.ස.)</p>"
