   "context": "",
   "html": "<p>නීතත්ථතො අවධාරණෙන කො අත්ථො එකන්තිකො කතො, අවධාරිතො චාති වුත්තං <strong>‘‘තත්ථා’’</strong>තිආදි. (දී.නි.ටී.)</p>"
