   "context": "<strong>ජර</strong> වයොහානිම්හි, ‘‘ජර මරාන’’න්තිආදිනා <strong>ජීර ජීය්‍යා</strong>දෙසා, ජීරතීති ජීරං, ජීරන්තී, ජීරන්තං, ජීරමානො, ජීරීයමානො, ජීයං, ජීයන්තී, ජීයන්තං, ජීයමානො<sup class=\"sn-mark sn-cur\">[1]</sup>, ජීය්‍යමානො.",
