   "context": "<strong>තස්මිං</strong>,*<sup class=\"sn-mark sn-cur\">[1]</sup> එහෙයි වෙසෙත් නුයි ගෙය තෙම ආවසථ නම් වේ; යු යනු <strong>මිස්සනෙ</strong>, මිශ්‍ර කිරීමෙහි වැටේ; එකක් කිරීමෙහි වැටේ; <strong>යුවතීති</strong>, මිශ්‍ර වේ නුයි; එක් වේනුයි සමූහය තෙම යූථ නම් වේ; දු යනු <strong>ගතිවුද්ධිම්හි</strong>, ගමන් වැඩීමෙහි වැටේ උඩට නැගිමෙහි වැටේ; දවති, සේ; <strong>වඩ්ඪතීති</strong>, වැඩෙනුයි රුක තෙම දුම නම් වේ; <strong>හිනොතීති</strong>, යේනුයි බහානුයි පිනි තෙම හිම නම් වේ; හි ගතිම්හි; <strong>සීයතීති</strong>, බඳනා ලැබේනුයි. සීම තෙම සීම නම් වේ; සීමා යනු ස්ත්‍රී ලිගුයි; දා යනු <strong>අවඛණ්ඩනෙ</strong>, කැඩීමෙහි වැටේ; <strong>දායතීති</strong>, කඩනු ලැබේනුයි දමතෙම දාම නම් වේ,",
