   "title": "නෙතීති, පැමිණේනුයි ඇස තෙම නෙත්ත නම් වේ…",
   "context": "",
   "html": "<p><strong>නෙතීති</strong>, පැමිණේනුයි ඇස තෙම නෙත්ත නම් වේ; විද යනු, <strong>මඞ්ගල්ලෙ</strong>, අභිවෘද්ධියෙහි වැටේ; <strong>පවිදතීති</strong>, පවිත්‍ර වේනුයි; අභිවෘද්ධියට පැමිණෙනුයි සුචිදෙය තෙම පවිත්ත නම් වේ.</p>"
