   "context": "",
   "html": "<p>පදති පාපුණාතීති පත්තො, පත්‍රො. ආහාරා පතන්ති එත්ථ භාජනෙති පත්තං, පත්‍රං. පදති පවත්තතීති වා පත්තං, පත්‍රං.</p>"
